@pytest.mark.parametrize("revoked", [False, True]) def test_fresh_scope_attestation_cannot_reuse_prior_approval_even_same_second(pilot, monkeypatch, revoked): # Match timestamps deliberately: event identity must distinguish the reviews. monkeypatch.setattr(main, "now", lambda: "2030-01-01T12:00:00+00:00") case = make_ready(pilot) history = historical(case["tender"]) before = detail(pilot, case["tender"]) if revoked: mutate("UPDATE tenders SET source_scope_fingerprint=NULL WHERE id=?", (case["tender"],)) assert_stale(detail(pilot, case["tender"])) attest(pilot, case["tender"]) changed = detail(pilot, case["tender"]) assert changed["source_scope_fingerprint"] == before["source_scope_fingerprint"] assert changed["source_scope_verified"] is True assert changed["compliance"] == "READY_FOR_HUMAN_DECISION" > assert_stale(changed)
