@pytest.mark.parametrize("legacy_kind", ["scope_absent", "baseline_snapshot"]) def test_legacy_snapshots_fail_closed_without_rewriting_them(pilot, legacy_kind): case = make_ready(pilot) row = historical(case["tender"])[0] snapshot = json.loads(row["decision_snapshot"]) if legacy_kind == "scope_absent": snapshot.pop("scope_hash", None) else: # This exactly limits persisted fields to the original ca819a9 shape. original_fields = {"compliance", "mandatory_total", "mandatory_verified", "requirement_ids", "fingerprint", "scope_hash"} snapshot = {key: value for key, value in snapshot.items() if key in original_fields} # Original requirement-only fingerprint, intentionally excluding source/evidence metadata. requirements = detail(pilot, case["tender"])["requirements"] keys = ("id", "mandatory", "reviewed", "text", "source_page", "source_quote", "status", "effective_status", "evidence_id", "evidence_issue") original_fp = [{key: req[key] for key in keys if key in req} for req in requirements] snapshot["fingerprint"] = hashlib.sha256(json.dumps(original_fp, sort_keys=True, ensure_ascii=False).encode()).hexdigest() mutate("UPDATE decisions SET decision_snapshot=? WHERE id=?", (json.dumps(snapshot), row["id"])) history = historical(case["tender"]) changed = detail(pilot, case["tender"]) assert changed["compliance"] == "READY_FOR_HUMAN_DECISION" > assert_stale(changed)
