@pytest.mark.parametrize("prefix", ["=SUM(1,2)", "+SUM(1,2)", "-SUM(1,2)", "@SUM(1,2)"]) @pytest.mark.parametrize("whitespace", ["", " ", "\t", "\r\n "]) def test_xlsx_all_user_fields_are_literal_with_prefix_and_whitespace_variants(pilot, prefix, whitespace): case = make_ready(pilot) payload = whitespace + prefix + " synthetic literal" # Preserve leading whitespace in synthetic persisted legacy records. API trims # most fields; direct DB writes ensure the export handles those legacy values. mutate("UPDATE tenders SET title=? WHERE id=?", (payload, case["tender"])) mutate("UPDATE requirements SET text=?,source_quote=?,notes=? WHERE id=?", (payload, payload, payload, case["req"])) mutate("UPDATE evidence SET label=? WHERE id=?", (payload, case["evidence"])) mutate("UPDATE decisions SET reviewer=?,rationale=? WHERE tender_id=?", (payload, payload, case["tender"])) history = historical(case["tender"]) response = call(pilot, "get", f"/api/tenders/{case['tender']}/export.xlsx") workbook = load_workbook(io.BytesIO(response.content), data_only=False) cells = [("Compliance Matrix", coordinate) for coordinate in ("B2", "E8", "G8", "H8", "I8")] cells += [("Decision History", coordinate) for coordinate in ("B2", "C2")] for sheet_name, coordinate in cells: cell = workbook[sheet_name][coordinate] > assert cell.data_type == "s", (sheet_name, coordinate, cell.value, cell.data_type) E AssertionError: ('Compliance Matrix', 'B2', '=SUM(1,2) synthetic literal', 'f') E assert 'f' == 's' E E - s E + f
